import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"ホットキー設定","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/settings/hotkeys-page.md","filePath":"ja-JP/user-guide/settings/hotkeys-page.md","lastUpdated":1787788413000}'),s={name:"ja-JP/user-guide/settings/hotkeys-page.md"};function a(n,o,i,c,d,g){return t(),r("div",null,[...o[0]||(o[0]=[l('<h1 id="ホットキー設定" tabindex="-1">ホットキー設定 <a class="header-anchor" href="#ホットキー設定" aria-label="Permalink to &quot;ホットキー設定&quot;">​</a></h1><p>ホットキー設定画面では、Lertaro の全グローバル呼び出しキー、アプリ内ナビゲーションキー、プラグインアクションショートカット、およびプロセスブラックリストを一元管理します。画面上部には <strong>グローバル</strong>、<strong>プラグインアクション</strong>、<strong>プロセスブラックリスト</strong> の 3 つのタブが配置されています。</p><h2 id="_1-グローバル-global" tabindex="-1">1. グローバル（Global） <a class="header-anchor" href="#_1-グローバル-global" aria-label="Permalink to &quot;1. グローバル（Global）&quot;">​</a></h2><h3 id="グローバルショートカット" tabindex="-1">グローバルショートカット <a class="header-anchor" href="#グローバルショートカット" aria-label="Permalink to &quot;グローバルショートカット&quot;">​</a></h3><ul><li><strong>クイック検索の表示/非表示</strong>：専用のキー登録欄。<strong>修飾キーの 2 回連打モード</strong>（既定は <code>Ctrl</code> の 2 回連打、<code>Alt</code> や <code>Shift</code> にも設定可能）または <strong>通常のキー組み合わせ</strong>（例: <code>Alt+Space</code>、<code>Win+Space</code> など）に対応。</li><li><strong>既定でメインウィンドウを開く</strong>：チェックボックス（既定は無効）。有効にすると、グローバル呼び出しキーでクイックウィンドウではなくメインウィンドウを開きます。初回表示時は一度だけ前面とフォーカスを処理し、表示中で非アクティブなら再アクティブ化、すでにアクティブならもう一度押すと閉じます。自動的に最前面へ固定されることはありません。</li><li><strong>全画面アプリフォーカス時も応答する</strong>：チェックボックス（既定は無効）。有効にすると、フルスクリーンのゲームや動画プレイヤーがアクティブな場合でもホットキーに応答します。無効のときはゲーム操作を保護するためにキーをスルーします。</li><li><strong>クイックジャンプ（Quick Jump）</strong>：既定は <code>Ctrl+G</code>。ファイルダイアログ内で直前にファイラーで開いていたフォルダーへ移動します。</li></ul><h3 id="機能キー" tabindex="-1">機能キー <a class="header-anchor" href="#機能キー" aria-label="Permalink to &quot;機能キー&quot;">​</a></h3><p>カスタムの単一キーまたは組み合わせキーを登録できるコントロール群です。</p><ul><li><strong>次の項目 / 前の項目を選択</strong>：既定 <code>Ctrl+N</code> / <code>Ctrl+P</code>（方向キー <code>↓</code> / <code>↑</code> と同等）。</li><li><strong>結果ジャンプ修饰キー</strong>：既定 <code>Ctrl</code>、数字キー <code>1</code>–<code>9</code> と組み合わせて直接起動。</li><li><strong>アクションメニューを開く</strong>：既定 <code>Ctrl+O</code>（方向キー <code>→</code> と同等）。</li><li><strong>選択項目で検索語を補完</strong>：既定 <code>Ctrl+Tab</code>。</li><li><strong>QuickLook 即時プレビュー</strong>：既定 <code>Alt+P</code>。</li><li><strong>前 / 次の検索履歴語</strong>：既定 <code>Alt+Up</code> / <code>Alt+Down</code>。</li><li><strong>現在の履歴語を削除</strong>：既定 <code>Ctrl+Delete</code>。</li><li><strong>メインウィンドウを開く</strong>：既定 <code>Ctrl+F</code>。</li><li><strong>LocalSend 画面を開く</strong>：既定 <code>Ctrl+S</code>。</li><li><strong>ウィンドウを固定（ピン留め）</strong>：既定 <code>Ctrl+T</code>。</li><li><strong>クイックパネルの表示/非表示</strong>：既定 <code>Ctrl+F2</code>。</li></ul><h3 id="クイックナビゲーション-マウス操作" tabindex="-1">クイックナビゲーション（マウス操作） <a class="header-anchor" href="#クイックナビゲーション-マウス操作" aria-label="Permalink to &quot;クイックナビゲーション（マウス操作）&quot;">​</a></h3><ul><li><strong>余白部分で左ダブルクリック</strong>：チェックボックス（既定で有効）。デスクトップやエクスプローラーの余白ダブルクリックでメニューを表示。</li><li><strong>余白部分で中クリック</strong>：チェックボックス（既定で有効）。デスクトップやエクスプローラー、ファイルダイアログで中クリックしてメニューを表示。</li></ul><h2 id="_2-プラグインアクション-plugin-actions" tabindex="-1">2. プラグインアクション（Plugin Actions） <a class="header-anchor" href="#_2-プラグインアクション-plugin-actions" aria-label="Permalink to &quot;2. プラグインアクション（Plugin Actions）&quot;">​</a></h2><p>各プラグインが登録したアクションショートカット（例: パスコピー <code>Ctrl+Shift+C</code>、切り取り <code>Ctrl+X</code>、コピー <code>Ctrl+C</code>、貼り付け <code>Ctrl+V</code>、削除 <code>Delete</code>、完全削除 <code>Shift+Delete</code> など）が一覧表示されます。</p><ul><li><strong>プラグインごとのグループ分け</strong>：提供元のプラグインごとに整理されています。</li><li><strong>個別の再登録</strong>：各アクションに専用の登録欄があり、新しいキーを押すだけで変更可能です。</li></ul><h2 id="_3-プロセスブラックリスト-process-blacklist" tabindex="-1">3. プロセスブラックリスト（Process Blacklist） <a class="header-anchor" href="#_3-プロセスブラックリスト-process-blacklist" aria-label="Permalink to &quot;3. プロセスブラックリスト（Process Blacklist）&quot;">​</a></h2><p>特定のアプリがフォアグラウンドにある際、Lertaro のホットキーやマウス操作を無効化するリストです。</p><ul><li><strong>大文字小文字の区別なし</strong>：<code>game.exe</code> または <code>game</code> のどちらでも一致します。</li><li><strong>個別追加</strong>：プロセス名を入力して <strong>プロセスを追加</strong> をクリック。</li><li><strong>テキストでの一括管理</strong>：<strong>テキスト生成</strong> で現在のリストを複数行テキストとしてエクスポートしたり、貼り付けて <strong>リストに適用</strong> で一括更新できます。</li><li><strong>ファイルダイアログの自動除外</strong>：ブラックリスト内のアプリであっても、Windows 標準のファイルダイアログが表示されているときはインライン検索やクイックナビゲーションが正常に動作します。</li></ul>',16)])])}const p=e(s,[["render",a]]);export{u as __pageData,p as default};
